 public static void main(String[] args)throws Exception{try(RandomAccessFile d=new RandomAccessFile("../koios-cache/main_file_cache.dat","r");RandomAccessFile i=new RandomAccessFile("../koios-cache/main_file_cache.idx0","r")){TextDrawingArea font=new TextDrawingArea(false,"p12_full",new StreamLoader(new Decompressor(d,i,1).decompress(1)));try{font=(TextDrawingArea)ExileTheme.class.getMethod("body").invoke(null);}catch(NoSuchMethodException old){}String[] state=new String[26];java.util.Arrays.fill(state,"0");state[0]="50";state[1]="50";state[6]="1";state[7]="1";state[13]="1";state[14]="0";state[15]="1";state[16]="2";canvas();SkillPanel.draw(font,new SkillDragState(),state,100,90);save("arsenal-refreshed");canvas();new ControlsPanel(InputBindings.sessionDefaults()).draw(font);save("controls-refreshed");canvas();state[0]="25";state[1]="50";SkillPanel.drawBar(font,state,new String[]{"Life: 50 / 100","Energy Shield: 0 / 0"});int top=SkillPanel.barTop(512,334);for(int x:new int[]{18,145}){if(DrawingArea.pixels[(top+25)*512+x+10]==DrawingArea.pixels[(top+25)*512+x+100])throw new AssertionError("Resource half fill must differ from empty tail");}save("resource-hud-refreshed");System.out.println("Rendered native arsenal, controls and half-filled resource HUD;2 fill checks passed.");}}
